// generated/concepts.ts -- bare-ids concept + CDC topic constants.
//
// SHAPE: this mirrors the memQL sdk-gen `generated_concepts.ts` output (the A3
// surface, engine PR znasllc-io/memql#2452): `Concepts` / `BoundConcepts` /
// `CDCTopics` / `CDCFilters` + the `topicFor` / `filterFor` helpers. In a real
// product this file is GENERATED by the engine's sdk-gen (from core DSL + this
// repo's dsl/__PRODUCT__/) and re-exported by @__PRODUCT_ORG__/__PRODUCT__-sdk.
// This starter ships a hand-seeded subset so the shell builds standalone;
// regenerate the full authoritative set from dsl/ and import these from the SDK
// instead.
//
// IDENTIFIER SAFETY: the object KEYS below use __PRODUCT_ID__ (the product name
// with hyphens mapped to underscores) so a hyphenated product (e.g. demo-app)
// stamps a valid TS identifier (demo_app_GREETING). The canonical `v1:` string
// VALUES use __PRODUCT_ID__ too: the engine's @namespace pattern is
// [a-z][a-z0-9_]* (no hyphens), so the concept registers as v1:demo_app:greeting
// and these VALUES must match it exactly (#38).
//
// THIS IS THE ONE PLACE canonical `v1:` ids may appear -- they are the DSL
// source of truth, machine-generated. Everywhere else in the app, refer to a
// concept THROUGH these constants; never hand-write a `v1:`-prefixed string or
// split an id on ':'. The bare-ids ESLint contract (eslint.config.js) enforces
// that and excludes this generated module.

// SEEDED SET: only concepts the ENGINE actually declares, plus this pack's own.
// `v1:cognition:space` used to be listed here and is NOT an engine concept --
// spaces are product-owned, delivered through a product's own DSL bundle at
// MEMQL_DSL_PATH, so a hand-seeded core entry for one was wrong. Regenerating
// against the engine is what keeps this honest.
//
// CDCFilters / CDCTopics ARE still emitted by sdk-gen, but a graph subscription
// no longer takes a filter STRING: the engine composes the bus topic from
// concept + actions and rejects a free-text filter for graph kinds
// (znasllc-io/memql#2460). Pass `Concepts.X` to MemqlClient.subscribeGraph;
// these two maps remain useful for logging, display, and the non-graph
// subscription kinds.

/** Canonical concept ids, keyed by SCREAMING_SNAKE of <namespace>_<concept>. */
export const Concepts = {
  COGNITION_PARTICIPANT: "v1:cognition:participant",
  IDENTITY_USER: "v1:identity:user",
  __PRODUCT_ID___GREETING: "v1:__PRODUCT_ID__:greeting",
} as const;
export type ConceptKey = keyof typeof Concepts;
export type ConceptId = (typeof Concepts)[ConceptKey];

/** Per-construct bound concept: generated method name -> canonical concept id. */
export const BoundConcepts = {
  // Populated by sdk-gen from the product's queries/mutations. Empty until the
  // product adds constructs and regenerates.
} as const;

/** Full emitted CDC topics: graph.node.<action>.<concept>. */
export const CDCTopics = {
  __PRODUCT_ID___GREETING_CREATED: "graph.node.created.v1:__PRODUCT_ID__:greeting",
  __PRODUCT_ID___GREETING_UPDATED: "graph.node.updated.v1:__PRODUCT_ID__:greeting",
  __PRODUCT_ID___GREETING_DELETED: "graph.node.deleted.v1:__PRODUCT_ID__:greeting",
} as const;

/** Subscription filters: node.<action>.<concept> (the backend prepends `graph.`). */
export const CDCFilters = {
  __PRODUCT_ID___GREETING_CREATED: "node.created.v1:__PRODUCT_ID__:greeting",
  __PRODUCT_ID___GREETING_UPDATED: "node.updated.v1:__PRODUCT_ID__:greeting",
  __PRODUCT_ID___GREETING_DELETED: "node.deleted.v1:__PRODUCT_ID__:greeting",
} as const;

export type CDCAction = "created" | "updated" | "deleted";

/** Compose a CDC topic for a concept id + action (matches sdk-gen's helper). */
export const topicFor = (concept: ConceptId | string, action: CDCAction = "created"): string =>
  `graph.node.${action}.${concept}`;

/** Compose a CDC subscription filter for a concept id + action. */
export const filterFor = (concept: ConceptId | string, action: CDCAction = "created"): string =>
  `node.${action}.${concept}`;
